                "guests", r.guests,
                "ratePlan", r.ratePlan.name(),
                "nights", r.nights,
                "subtotal", r.subtotal.doubleValue(),
                "discount", r.discount.doubleValue(),
                "total", r.total.doubleValue(),
                "status", r.status.name(),
                "amountPaid", r.amountPaid.doubleValue(),
                "refund", r.refund != null ? r.refund.doubleValue() : null
        );
    }

    private static Map<String, Object> documentToJson(Document d) {
        return Map.of(
                "title", d.title,
                "reservationId", d.reservationId,
                "guestName", d.guestName,
                "guestCpf", d.guestCpf,
                "roomNumber", d.roomNumber,
                "roomType", d.roomType,
                "checkIn", d.checkIn.toString(),
                "checkOut", d.checkOut.toString(),
                "nights", d.nights,
                "subtotal", d.subtotal.doubleValue(),
                "discount", d.discount.doubleValue(),
                "total", d.total.doubleValue()
        );
    }
}

